7	    // The shim relies on glibc's open/open64/fstat/fstat64 interposition
8	    // semantics; build it on Linux. On other Unix targets the shim-backed
9	    // tests detect the missing env var and skip themselves, while the
10	    // shim-free tests still run.
11	    if target_os != "linux" {
12	        println!("cargo:warning=permfail shim not built for target OS {target_os}; shim-backed tests will skip");
13	        return;
14	    }
15	
16	    let out_dir = std::path::PathBuf::from(std::env::var("OUT_DIR").unwrap());
17	    let so_path = out_dir.join("libwrapfile_permfail.so");
18	    let src = "tests/support/permfail/permfail.c";
19	
20	    let cc = std::env::var("CC").unwrap_or_else(|_| "cc".to_string());
21	    let status = std::process::Command::new(&cc)
22	        .args(["-O0", "-g", "-fPIC", "-shared", "-Wall", "-Wextra"])
23	        .arg("-o")
24	        .arg(&so_path)
25	        .arg(src)
26	        .status();
27	
28	    match status {
29	        Ok(s) if s.success() => {}
30	        Ok(s) => panic!("permfail shim compile failed with status {s}"),
31	        // A machine without a C compiler can still build/use wrapfile
32	        // itself; skip exporting the shim path so the shim-backed tests
33	        // print a skip notice. A compiler that ran but rejected the source
34	        // is a real error and must fail loudly (the Ok arm above).
35	        Err(e) if e.kind() == std::io::ErrorKind::NotFound => {
36	            println!("cargo:warning=C compiler '{cc}' not found; permfail shim not built, shim-backed tests will skip");
37	            return;
