533	    assert!(!key.exists());
534	    sibling.assert_untouched();
535	    assert_eq!(mode_of(&tmp.path), parent_mode_before, "parent directory must be untouched");
536	
537	    // A retry *without* the fault succeeds normally and produces only the key.
538	    let trace2 = prepare_trace(&tmp.path, "trace2.log");
539	    let run2 = run_keygen(&key, 0o022, Some(&so), &[], Some(&trace2));
540	    assert_key_file_ok(&key, &run2);
541	    sibling.assert_untouched();
