int fsync(int fd) {
    if (!real_fsync) real_fsync = dlsym(RTLD_NEXT, "fsync");
    if (!process_active()) return real_fsync(fd);
    load_config();
    if (is_tracked(fd) && cfg_fail_fsync) {
