{
    if (!real_fchmod)
        real_fchmod = (fchmod_fn)dlsym(RTLD_NEXT, "fchmod");

    if (!process_active())
        return real_fchmod(fd, mode);
    load_config();

    if (is_tracked(fd) && cfg_fail_fchmod) {
